// 判断是否包含 "Publish Message"
if (!info || !info.includes("Publish Message")) {
    node.warn("Row " + N + " does not contain Publish Message.");
    return null;
}
node.warn("Row " + N + " has contain Publish Message.");

var messages = info.split(",");  // 按逗号分割多个 Publish Message
var results = [];

// 拆分多个 JSON 对象：以 `},{` 为分界，但用 lookaround 保留完整结构
var payloads = payload.split(/(?<=\})\s*,\s*(?=\{)/);
node.warn("Payloads after split: " + JSON.stringify(payloads));

var topicIndex = 0;

messages.forEach(function(message) {
    var topicMatch = message.match(/\[([^\]]+)\]/);  // 提取 [topic]
    if (topicMatch) {
        var topic = topicMatch[1];
        var entry = {
            timestamp: new Date().toISOString(),
            id: N,
            topic: topic,
            payload: payloads[topicIndex] || null
        };
        node.warn("Matched topic: " + topic + " with payload: " + entry.payload);
        results.push(entry);
        topicIndex++;
    } else {
        node.warn("No topic match found in message: " + message);
    }
});

results.forEach(function(entry) {
    var outMsg = {
        topic: entry.topic,
        payload: {
            timestamp: entry.timestamp,
            id: entry.id,
            topic: entry.topic,
            payload: entry.payload
        }
    };
    node.warn(outMsg);
    node.send(outMsg);
});
return null;

