var rows = msg.payload;          
// 获取当前行号（N）
var N = msg.N;                   
// 获取全局 ACK 计数器
var globalACKCounter = flow.get('globalACKCounter') || 0;  

// 边界检查，确保当前行存在
if (N > rows.length || !rows[N-1]) {
    node.warn("Row " + N + " is out of bounds.");
    return null;
}

var row = rows[N-1];             // 获取第 N 行的数据
var info = row["Info"];          // 提取 Info 字段

node.warn("N = " + N);
node.warn("Info = " + info);

//////counter W6
let count = global.get("counter") || 0;
global.set("counter", count);
node.warn("W5:Counter = " + count);
if (count > 80) {
    node.warn("W5: Counter limit exceeded. Stopping further operations. Current value: " + count);
