// 正则匹配 ACK 类型
var ackMatch = info.match(/(Connect Ack|Publish Ack|Subscribe Ack)/);

if (ackMatch) {
    var msgType = ackMatch[1];  // 获取 ACK 类型（Connect Ack, Publish Ack, Subscribe Ack）
    node.warn("ackMatch = " + ackMatch);
    var subId = N;              // 假设 SUB_ID 为行号 N
    globalACKCounter++;         // 增加 ACK 计数器

    // 获取当前时间戳
    var timestamp = new Date().toISOString();

    // 构建 ACK 数据
    var ackData = {
        No: globalACKCounter,
        TIMESTAMP: timestamp,
        SUB_ID: subId,
        MSG_TYPE: msgType
    };

    // 更新全局 ACK 计数器
    flow.set('globalACKCounter', globalACKCounter);
    node.warn("Ack Counter = " + globalACKCounter);
    node.warn("msg.payload (ackData) = " + JSON.stringify(ackData));  // 输出 ackData

    // 将 globalACKCounter 添加到 msg 对象中，便于 HTTP 请求使用
    msg.globalACKCounter = globalACKCounter;
    node.warn("msg.globalACKCounter = "+msg.globalACKCounter);

    // 构建 ThingSpeak 请求的 payload

// 构造 HTTP 请求消息
    var httpMsg = {
        url: "https://api.thingspeak.com/update?api_key=YOUR_THINGSPEAK_WRITE_API_KEY&field2=" + globalACKCounter,
        payload: ""
    };

    // 发送两个不同的消息，分别给不同模块
    node.send([
        httpMsg,               // 发送给 HTTP Request
        { payload: ackData },  // 发送给 CSV
    ]);

    return null;  // return null，因为我们用的是 node.send()
}

